function climbStairs(n) {
  if (n <= 2) return n;

  let prev2 = 1; // ways to reach step (i - 2), starts as ways to reach step 1
  let prev1 = 2; // ways to reach step (i - 1), starts as ways to reach step 2

  for (let i = 3; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }

  return prev1;
}

function rob(nums) {
  let prevMax = 0; // best total using houses up to i-2
  let currMax = 0; // best total using houses up to i-1

  for (const num of nums) {
    const robThis = prevMax + num;
    const temp = Math.max(currMax, robThis);
    prevMax = currMax;
    currMax = temp;
  }

  return currMax;
}

function rob(nums) {
  const n = nums.length;
  if (n === 1) return nums[0];

  const robLinear = (houses) => {
    let prevMax = 0;
    let currMax = 0;
    for (const num of houses) {
      const temp = Math.max(currMax, prevMax + num);
      prevMax = currMax;
      currMax = temp;
    }
    return currMax;
  };

  return Math.max(
    robLinear(nums.slice(0, n - 1)), // exclude the last house
    robLinear(nums.slice(1))         // exclude the first house
  );
}

function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;

  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      if (coin <= a && dp[a - coin] + 1 < dp[a]) {
        dp[a] = dp[a - coin] + 1;
      }
    }
  }

  return dp[amount] === Infinity ? -1 : dp[amount];
}

