function numDecodings(s) {
  const n = s.length;
  if (n === 0) return 0;

  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  dp[1] = s[0] !== '0' ? 1 : 0;

  for (let i = 2; i <= n; i++) {
    const oneDigit = Number(s.slice(i - 1, i));
    const twoDigit = Number(s.slice(i - 2, i));

    if (oneDigit >= 1) {
      dp[i] += dp[i - 1];
    }
    if (twoDigit >= 10 && twoDigit <= 26) {
      dp[i] += dp[i - 2];
    }
  }

  return dp[n];
}

function uniquePaths(m, n) {
  const dp = new Array(n).fill(1); // first row: exactly one way to reach every cell

  for (let row = 1; row < m; row++) {
    for (let col = 1; col < n; col++) {
      dp[col] += dp[col - 1]; // dp[col] currently holds "paths from above"; add "paths from the left"
    }
  }

  return dp[n - 1];
}

